import type { Role } from '../app'
import type { PropertyType } from '../fluent/tables'

type Property<T extends PropertyType = PropertyType> = Now.Internal.WithID<
    {
        /** Name of the property */
        name: string
        /** Data type for the property */
        type?: T | ''
        /** The desired value for the property */
        value?: string | number | boolean
        /** A brief, descriptive phrase describing the function of the property */
        description?: string
        /** Determines whether to flush this property's value from all other server-side caches */
        ignoreCache?: boolean
        /** If true, exclude this property from being imported via update sets */
        isPrivate?: boolean
        /** Comma-separated values for a choice list */
        choices?: string[]
        /** The roles that have access to this property */
        roles?: {
            read?: (Role | string)[] | undefined
            write?: (Role | string)[] | undefined
        }
    } & Now.Internal.Meta
>

/**
 * Creates a system property (`sys_properties`).
 *
 * @see https://docs.servicenow.com/csh?topicname=property-api-now-ts.html&version=latest
 *
 * @param config - an object containing the following properties:
 *   * **name** - name of the property
 *   * **choices**? - comma-separated values for a choice list
 *   * **description**? - a brief, descriptive phrase describing the function of the property
 *   * **ignoreCache**? - determines whether to flush this property's value from all other server-side caches
 *   * **isPrivate**? - if true, exclude this property from being imported via update sets
 *   * **roles**? - the roles that have access to this property
 *   * **type**? - data type for the property
 *   * **value**? - the desired value for the property
 */
export function Property<const T extends PropertyType>(config: Property<T>): Property<T> {
    return config
}
